 let seed = Math.random() * 9999;
 let mySize;
 let angle_c;
 let palette;
 let colors = [];
 let colors7 = "fefefe-292929-ffffff-222222-202020".split("-").map((a) => "#" + a);
 let colors8 = "8c75ff-c553d2-2dfd60-2788f5-23054f-f21252-8834f1-c4dd92-184fd3-f9fee2-2E294E-541388-F1E9DA-FFD400-D90368-e9baaa-ffa07a-164555-ffe1d0-acd9e7-4596c7-6d8370-e45240-21d3a4-3303f9-cd2220-173df6-244ca8-a00360-b31016".split("-").map((a) => "#" + a);
 var color_setup1, color_setup2;
 let color_bg;
 let branch;

 function setup() {
 	// pixelDensity(4);
 	// mySize = 1000;
 	// frameRate(120);
 	mySize = max(windowWidth, windowHeight);
 	createCanvas(mySize, mySize);
 	colorMode(HSB, 360, 100, 100, 100);
 	palette = random(colorScheme).colors.concat();
 	if (int(seed) % 2 == 0) {
 		color_setup1 = random(colorScheme).colors.concat();
 		color_setup2 = random(colorScheme).colors.concat();
 	} else {
 		color_setup1 = colors7;
 		color_setup2 = colors8;
 	}
	 //black & white
	 // color_setup1 = colors7;
	 // color_setup2 = colors7
	 // color_bg = "#fff";
 	color_bg = "#000000";
 	background(color_bg);
 	angle_c = 0;
 	branch = int(random(4, 20));
 }

 function draw() {
  // === Variant 4: Dynamic Feedback Trail ===
  // Lower background clear to force deep visual echoing

 	randomSeed(seed);
 	drawingContext.shadowColor = str(random(color_setup1)) + "00";
 	drawingContext.shadowOffsetX = 0;
 	drawingContext.shadowOffsetY = 0;
 	drawingContext.shadowBlur = 0;
 	translate(width / 2, height / 2);
 	rotate(angle_c);
 	for (let i = 0; i < 2; i++) {
 		colors[0] = random(color_setup1);
 		colors[1] = random(color_setup1);
 		colors[2] = random(color_setup1);
 		colors[3] = random(color_setup2);
 		colors[4] = random(color_setup2);
 		circleForm(0, 0, mySize * 0.85 * (i + 1) / 2);
 	}
 	if (frameCount % 100 == 0 && branch < 1000) {
 		branch += 10;
 		angle_c += TAU / 360;
 	} else if (branch >= 1000) {
 		branch = 4;
 		frameCount = 0;
 	}
 }

